SAMPLE_LINES = [line.strip() for line in SAMPLE_TEXT.splitlines() if line.strip()]


def test_parse_combatant_info_inline() -> None:
    """Valida parsing de COMBATANT_INFO usando amostras inline."""
    processor = CombatLogProcessor()
    events = [
        ev
        for line in SAMPLE_LINES
        if (ev := processor.parse_line(line)) is not None
    ]

    assert len(events) == 2
    assert all(ev["event"] == "COMBATANT_INFO" for ev in events)

    ci_by_guid = {ev["player"]["guid"]: ev for ev in events}

    assert ci_by_guid["Player-580-08A1815D"]["stats"]["strength"] == 2171
    assert ci_by_guid["Player-60-0E9BD0FE"]["stats"]["strength"] == 7550
    assert ci_by_guid["Player-580-08A1815D"]["pvp_stats"]["Rating"] == 288
    assert ci_by_guid["Player-60-0E9BD0FE"]["pvp_stats"]["Rating"] == 1353

    ci_sample = ci_by_guid["Player-580-08A1815D"]

    expected_first_talent = {"talent_id": 90636, "spell_id": 112521, "rank": 1}
    assert ci_sample["class_talents"][0] == expected_first_talent
    assert [t["talent_id"] for t in ci_sample["class_talents"][:3]] == [90636, 90637, 90684]

    expected_first_item = {
        "item_id": 205575,
        "item_level": 450,
        "enchants": [],
        "bonus_list": [9430, 9420, 9223, 9221, 6652, 9415, 1485, 8767],
        "gems": [],
    }
    assert ci_sample["equipment"][0] == expected_first_item
    assert [item["item_id"] for item in ci_sample["equipment"][:3]] == [205575, 205788, 193406]

    item_with_gems = ci_sample["equipment"][1]
    assert item_with_gems["item_id"] == 205788
    assert item_with_gems["item_level"] == 437
    assert item_with_gems["bonus_list"] == [9421, 9419, 6652, 1472, 8766, 9477, 8782]
    assert len(item_with_gems["gems"]) == 3
    assert item_with_gems["gems"][0] == {"id": 192964, "item_level": 415}

    json.dumps(events, ensure_ascii=False)
